P = params(w=100.0, d=60.0, h=20.0, hole_d=40.0)
def gen_step():
    blk = box(P.w, P.d, P.h, at=CENTER)
    hole = cylinder(P.hole_d/2.0, P.h+2.0, at=(0.0, 0.0, -1.0))
    return solid(cut(blk, hole), label="plate")

